int calculateOffset(int arrayLength, int index, int element) {
    // Check if the index is within the bounds of the array
    if (index < 0 || index >= arrayLength) {
        throw new IndexOutOfBoundsException("Index out of bounds");
    }

    // Calculate the offset by subtracting the array length from the index
    int offset;

    // If element is 0, set offset to 0
    if (element == 0) {
        offset += arrayLength;
    } else {
        // Otherwise, calculate offset as array length minus the index
        offset = arrayLength - index;
    }

    return offset;  // Return the calculated offset
}
```

